<?php
require __DIR__.'/bootstrap.php';require_roles(['admin','accountant']);$branch=is_admin()?null:require_branch();$id=(int)($_GET['id']??$_POST['id']??0);
$get=$pdo->prepare('SELECT * FROM general_invoices WHERE id=?'.($branch===null?'':' AND branch_id='.(int)$branch));$get->execute([$id]);$invoice=$get->fetch();if(!$invoice){http_response_code(404);exit('Invoice not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$des=$_POST['item_description']??[];$kgs=$_POST['item_kg']??[];$rates=$_POST['item_rate']??[];$items=[];$total=0;foreach($des as $i=>$d){$d=trim($d);$kg=(float)($kgs[$i]??0);$rate=(float)($rates[$i]??0);if($d===''||$kg<=0||$rate<=0){flash('danger','Every item needs description, KG, and rate.');redirect('general_invoice_edit.php?id='.$id);}$amount=round($kg*$rate,2);$items[]=[$d,$kg,$rate,$amount];$total+=$amount;}if(!$items){flash('danger','Add at least one item.');redirect('general_invoice_edit.php?id='.$id);}$pdo->beginTransaction();try{$pdo->prepare('UPDATE general_invoices SET receiver=?,phone=?,description=?,kg=?,rate=?,amount=?,issue_date=?,due_date=?,notes=? WHERE id=?')->execute([trim($_POST['receiver']),trim($_POST['phone']),$items[0][0],$items[0][1],$items[0][2],$total,$_POST['issue_date'],$_POST['due_date'],trim($_POST['notes']),$id]);if($invoice['status']==='Paid')$pdo->prepare('UPDATE payments SET amount=? WHERE general_invoice_id=? AND reference_no=CONCAT(\'GINV-\',?)')->execute([$total,$id,$invoice['invoice_no']]);$pdo->prepare('DELETE FROM general_invoice_items WHERE general_invoice_id=?')->execute([$id]);$add=$pdo->prepare('INSERT INTO general_invoice_items(general_invoice_id,description,kg,rate,amount) VALUES(?,?,?,?,?)');foreach($items as $item)$add->execute([$id,...$item]);$pdo->commit();flash('success','Invoice updated.');redirect('general_invoices.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Invoice could not be updated.');redirect('general_invoice_edit.php?id='.$id);}}
$items=$pdo->prepare('SELECT * FROM general_invoice_items WHERE general_invoice_id=? ORDER BY id');$items->execute([$id]);$items=$items->fetchAll();if(!$items)$items=[['description'=>$invoice['description'],'kg'=>$invoice['kg'],'rate'=>$invoice['rate']]];$title='Edit general invoice';require __DIR__.'/partials/header.php';
?><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 fw-bold mb-1">Edit <?=e($invoice['invoice_no'])?></h1><p class="text-secondary mb-0">Update customer details and invoice items.</p></div><a class="btn btn-outline-secondary" href="general_invoices.php">Back</a></div><form method="post" class="card border-0 shadow-sm p-3 p-lg-4"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$id?>"><div class="row"><div class="col-md-7"><label class="form-label">Receiver / customer</label><input class="form-control mb-3" name="receiver" value="<?=e($invoice['receiver'])?>" required></div><div class="col-md-5"><label class="form-label">Phone</label><input class="form-control mb-3" name="phone" value="<?=e($invoice['phone'])?>"></div></div><div class="d-flex justify-content-between align-items-center"><h2 class="h6">Invoice items</h2><button id="addItem" type="button" class="btn btn-sm btn-outline-primary">Add item</button></div><div class="table-responsive"><table class="table" id="itemsTable"><thead><tr><th>Description</th><th>KG</th><th>Rate</th><th>Amount</th><th></th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><input class="form-control" name="item_description[]" value="<?=e($item['description'])?>" required></td><td><input class="form-control item-kg" type="number" step=".01" min=".01" name="item_kg[]" value="<?=e($item['kg'])?>" required></td><td><input class="form-control item-rate" type="number" step=".01" min=".01" name="item_rate[]" value="<?=e($item['rate'])?>" required></td><td class="item-amount"></td><td><button type="button" class="btn btn-sm btn-outline-danger remove-item"><i class="bi bi-trash"></i></button></td></tr><?php endforeach?></tbody><tfoot><tr><th colspan="3" class="text-end">Total Amount</th><th id="invoiceTotal" class="text-primary"></th><th></th></tr></tfoot></table></div><div class="row"><div class="col"><label class="form-label">Issue date</label><input class="form-control" type="date" name="issue_date" value="<?=e($invoice['issue_date'])?>" required></div><div class="col"><label class="form-label">Due date</label><input class="form-control" type="date" name="due_date" value="<?=e($invoice['due_date'])?>" required></div></div><label class="form-label mt-3">Notes</label><textarea class="form-control" name="notes"><?=e($invoice['notes'])?></textarea><div class="text-end mt-4"><button class="btn btn-primary px-4">Save changes</button></div></form><script>const body=document.querySelector('#itemsTable tbody');const tpl=()=>`<tr><td><input class="form-control" name="item_description[]" required></td><td><input class="form-control item-kg" type="number" step=".01" min=".01" name="item_kg[]" required></td><td><input class="form-control item-rate" type="number" step=".01" min=".01" name="item_rate[]" required></td><td class="item-amount"></td><td><button type="button" class="btn btn-sm btn-outline-danger remove-item"><i class="bi bi-trash"></i></button></td></tr>`;function sum(){let n=0;body.querySelectorAll('tr').forEach(r=>{const a=(+r.querySelector('.item-kg').value||0)*(+r.querySelector('.item-rate').value||0);r.querySelector('.item-amount').textContent=a.toFixed(2);n+=a});document.querySelector('#invoiceTotal').textContent=n.toFixed(2)}document.querySelector('#addItem').onclick=()=>{body.insertAdjacentHTML('beforeend',tpl());sum()};body.oninput=sum;body.onclick=e=>{if(e.target.closest('.remove-item')&&body.rows.length>1){e.target.closest('tr').remove();sum()}};sum()</script><?php require __DIR__.'/partials/footer.php';?>
